<?php
namespace App\Infrastructure\Repositories\Eloquent;
use App\Domain\Contracts\Repositories\OrderRepositoryInterface;use App\Domain\Models\Cart;use App\Domain\Models\Order;use App\Domain\Models\CartItem;use App\Domain\Models\Product;use App\Domain\Models\ProductVariant;
class OrderRepository implements OrderRepositoryInterface{public function cartForCheckout(string $userId):?Cart{return Cart::where('user_id',$userId)->with(['items.product','items.variant'])->lockForUpdate()->first();}public function create(array $data):Order{return Order::create($data);}public function addItem(Order $order,array $data):void{$order->items()->create($data);}public function decrementStock(CartItem $item):void{if($item->variant)$item->variant->decrement('stock_quantity',$item->quantity);else $item->product->decrement('stock',$item->quantity);}public function incrementStock(string $productId,?string $variantId,int $quantity):void{if($variantId)ProductVariant::whereKey($variantId)->increment('stock_quantity',$quantity);else Product::whereKey($productId)->increment('stock',$quantity);}public function incrementCoupon(object $coupon):void{$coupon->increment('used_count');}public function recordCoupon(object $coupon,string $userId,string $orderId,float $discount):void{\App\Domain\Models\CouponUsage::create(['coupon_id'=>$coupon->id,'user_id'=>$userId,'order_id'=>$orderId,'discount_amount'=>$discount]);}public function clearCart(Cart $cart):void{$cart->items()->delete();}public function listForUser(string $userId){return Order::with('items')->where('user_id',$userId)->latest()->paginate(15);}public function listAll(){return Order::with('items')->latest()->paginate(30);}public function findForUser(string $userId,string $orderId):Order{return Order::with('items')->where('user_id',$userId)->findOrFail($orderId);}public function lock(string $id):Order{return Order::with('items')->lockForUpdate()->findOrFail($id);}}
